import 'dart:math';
enum MissionEventType { civilianSurvivor, corruptedCache, voxDistress, inquisitorialOrder, falseSignal, woundedAcolyte }
class MissionEvent { final MissionEventType type; final String title,description,choiceA,choiceB; final int alarmDelta,requisitionDelta; const MissionEvent(this.type,this.title,this.description,this.choiceA,this.choiceB,{this.alarmDelta=0,this.requisitionDelta=0}); }
class MissionEventDirector { final Random _random; MissionEventDirector({int? seed}):_random=Random(seed); MissionEvent roll({required int floor,required int alarm,int? seed}) {final r=seed==null?_random:Random(seed+floor*13+alarm);final all=<MissionEvent>[const MissionEvent(MissionEventType.civilianSurvivor,'Выживший рабочий','Он видел, кто открыл ворота культистам.','Эвакуировать','Допросить',alarmDelta:-2,requisitionDelta:3),const MissionEvent(MissionEventType.corruptedCache,'Осквернённый тайник','Внутри оружие и следы варп-коррупции.','Очистить','Забрать рискнув',alarmDelta:2,requisitionDelta:8),const MissionEvent(MissionEventType.voxDistress,'Сигнал бедствия','Повреждённый вокс повторяет координаты отряда.','Ответить','Сохранить тишину',alarmDelta:1,requisitionDelta:4),const MissionEvent(MissionEventType.inquisitorialOrder,'Приказ Инквизиции','Приоритетная цель замечена неподалёку.','Выполнить','Игнорировать',alarmDelta:-1,requisitionDelta:10),const MissionEvent(MissionEventType.falseSignal,'Ложная сигнатура','Ауспекс фиксирует подозрительно чистый сигнал.','Проверить','Обойти',alarmDelta:3,requisitionDelta:0),const MissionEvent(MissionEventType.woundedAcolyte,'Раненый аколит','Он просит стимулятор и предлагает сведения.','Помочь','Оставить',alarmDelta:-1,requisitionDelta:5)];return all[r.nextInt(all.length)];} }
